CREATE OR REPLACE FUNCTION public.consultora_pos_venda_prazo(_order uuid) RETURNS jsonb LANGUAGE sql STABLE SECURITY DEFINER SET search_path=public AS $$ SELECT jsonb_build_object('compra_em',(coalesce(o.pay_paid_at,o.created_at) AT TIME ZONE 'America/Sao_Paulo')::date,'hoje',(now() AT TIME ZONE 'America/Sao_Paulo')::date,'troca_ate',(coalesce(o.pay_paid_at,o.created_at) AT TIME ZONE 'America/Sao_Paulo')::date+45,'garantia_ate',((coalesce(o.pay_paid_at,o.created_at) AT TIME ZONE 'America/Sao_Paulo')::date+interval '2 years')::date) FROM public.sales_orders o WHERE o.id=_order AND auth.uid() IS NOT NULL AND public.has_role(auth.uid(),'consultora') AND o.consultora_party_id=public.my_party_id() AND o.payment_status='pago' AND o.status<>'cancelado'; $$;
REVOKE ALL ON FUNCTION public.consultora_pos_venda_prazo(uuid) FROM PUBLIC,anon;
GRANT EXECUTE ON FUNCTION public.consultora_pos_venda_prazo(uuid) TO authenticated,service_role;